341	export function sheetId(): string {
342	  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
343	}
344	
345	/** The id a creating helper returned; throws when the screen refused (null) so the failure
346	 *  lands on the arranging line rather than on a later assertion. */
347	export function must(id: string | null): string {
348	  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
349	  return id;
