351	
352	function escapeRe(s: string): string {
353	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
354	}
355	
356	/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
357	 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
358	 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
359	async function shown(loc: Locator): Promise<string> {
360	  return ((await loc.allTextContents())[0] ?? '').trim();
361	}
362	
363	/** The ids carried by every element matching `loc`, read without waiting. */
364	async function ids(loc: Locator, prefix: string): Promise<string[]> {
365	  const out: string[] = [];
366	  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
367	  return out;
368	}
